describe('Login Spinner', () => {
    beforeEach(() => {
        cy.visit('/login');
    });

    it('should display spinner during async login request', () => {
        cy.intercept('POST', '/api/login', {
            delay: 2000,
            statusCode: 200,
            body: { token: 'fake_token' }
        }).as('loginRequest');

        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('password123');
        cy.get('button[type="submit"]').click();

        cy.get('.spinner').should('be.visible');
        cy.wait('@loginRequest');
        cy.get('.spinner').should('not.exist');
        cy.url().should('include', '/dashboard');
    });

    it('should handle login failure without spinner', () => {
        cy.intercept('POST', '/api/login', {
            statusCode: 401,
            body: { error: 'Invalid credentials' }
        }).as('loginRequest');

        cy.get('input[name="username"]').type('wronguser');
        cy.get('input[name="password"]').type('wrongpassword');
        cy.get('button[type="submit"]').click();

        cy.get('.spinner').should('not.exist');
        cy.get('.error-message').should('be.visible').and('contain', 'Invalid credentials');
    });
});
